use super::*;

/// A ref's latch status as a short label.
pub(crate) fn status_of(s: &CoordState, r: &CoordRef) -> &'static str {
    match s.latches.get(&ref_key(r)) {
        Some(LatchStatus::Satisfied { .. }) => "satisfied",
        Some(LatchStatus::Failed { .. }) => "failed",
        None => "pending",
    }
}
